import java.util.*;

public class Main {
    int maxSatisfied(int[] customers, int[] grumpy, int minutes) {
        int n = customers.length;
        int best = 0;
        for (int start = 0; start <= n - minutes; start++) {
            int total = 0;
            for (int i = 0; i < n; i++) {
                if (i >= start && i < start + minutes) {
                    total += customers[i];                                        // secret technique active, every customer here is satisfied
                } else if (grumpy[i] == 0) {
                    total += customers[i];                                        // owner is already not grumpy here
                }
            }
            best = Math.max(best, total);
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxSatisfied(new int[]{1, 0, 1, 2, 1, 1, 7, 5}, new int[]{0, 1, 0, 1, 0, 1, 0, 1}, 3));
    }
}

